package com.ruoyi.web.controller.shop;
import java.util.*;import java.io.*;import java.nio.file.*;import java.time.*;import java.util.zip.*;import java.util.concurrent.TimeUnit;import java.security.MessageDigest;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.scheduling.annotation.Scheduled;import com.alibaba.fastjson2.*;
@Service public class ShopBackups {
 @Value("${shop.backup.enabled:false}") boolean enabled;@Value("${shop.backup.path:../runtime/backups}") String root;@Value("${shop.backup.mysqldump:mysqldump}")String dumpCommand;@Value("${spring.datasource.druid.master.url}")String jdbc;@Value("${spring.datasource.druid.master.username}")String username;@Value("${spring.datasource.druid.master.password}")String password;@Value("${shop.asset-path:../runtime/assets}")String assets;@Value("${shop.private-path:../runtime/private}")String privateFiles;@Value("${ruoyi.profile}")String uploads;
 private volatile boolean running=false;
 public Map<String,Object> status(){Map<String,Object> result=new LinkedHashMap<>();result.put("enabled",enabled);result.put("running",running);result.put("retentionDays",7);result.put("schedule","每天03:20（北京时间，服务运行期间）");try{Path state=Paths.get(root).resolve("status.json");if(Files.exists(state))result.putAll(JSON.parseObject(new String(Files.readAllBytes(state),java.nio.charset.StandardCharsets.UTF_8)));Path restore=Paths.get(root).resolve("restore-check.json");if(Files.exists(restore))result.put("restore",JSON.parseObject(new String(Files.readAllBytes(restore),java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception ignored){}return result;}
 @Scheduled(cron="0 20 3 * * ?",zone="Asia/Shanghai") public void daily(){if(enabled)try{backup();}catch(Exception e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("每日备份未完成，请查看后台运维状态");}}
 public synchronized Map<String,Object> backup()throws Exception{ShopService.check(enabled,"当前环境未开启自动备份，请由运维管理员配置独立备份目录");ShopService.check(!running,"备份正在进行，请稍后查看");running=true;long started=System.currentTimeMillis();Path dir=Paths.get(root).toAbsolutePath().normalize();Files.createDirectories(dir);Path dump=dir.resolve("current-dump.sql"),tmp=dir.resolve("current-backup.tmp");Process process=null;Map<String,Object> state=new LinkedHashMap<>();try{java.net.URI uri=java.net.URI.create(jdbc.substring("jdbc:".length()));String database=uri.getPath().substring(1);ShopService.check(database.matches("[a-zA-Z0-9_]+"),"数据库名称不适合当前备份方式");ProcessBuilder builder=new ProcessBuilder(dumpCommand,"--no-defaults","--host="+uri.getHost(),"--port="+(uri.getPort()>0?uri.getPort():3306),"--user="+username,"--single-transaction","--routines","--events","--triggers","--set-gtid-purged=OFF","--default-character-set=utf8mb4",database);builder.environment().put("MYSQL_PWD",password);builder.redirectOutput(dump.toFile());builder.redirectError(ProcessBuilder.Redirect.PIPE);process=builder.start();final InputStream errors=process.getErrorStream();Thread drain=new Thread(()->{try{byte[] b=new byte[1024];while(errors.read(b)>=0){}}catch(IOException ignored){}});drain.setDaemon(true);drain.start();ShopService.check(process.waitFor(180,TimeUnit.SECONDS)&&process.exitValue()==0,"数据库备份未完成，请检查服务账号和备份工具");String name="beauty-v3-"+LocalDate.now(ZoneId.of("Asia/Shanghai"))+".zip";try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(tmp))){entry(zip,dump,"database.sql");tree(zip,Paths.get(assets),"assets/");tree(zip,Paths.get(privateFiles),"private/");tree(zip,Paths.get(uploads),"uploads/");JSONObject manifest=new JSONObject();manifest.put("createdAt",Instant.now().toString());manifest.put("database",database);manifest.put("scope","数据库、商品及页面图片、私有凭证");zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(JSON.toJSONBytes(manifest));zip.closeEntry();}Path finalPath=dir.resolve(name);Files.move(tmp,finalPath,StandardCopyOption.REPLACE_EXISTING);MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream input=Files.newInputStream(finalPath)){byte[] buffer=new byte[65536];int size;while((size=input.read(buffer))>=0)sha.update(buffer,0,size);}StringBuilder hex=new StringBuilder();for(byte b:sha.digest())hex.append(String.format("%02x",b));state.put("lastSuccess",Instant.now().toString());state.put("archive",name);state.put("sha256",hex.toString());state.put("bytes",Files.size(finalPath));state.put("seconds",(System.currentTimeMillis()-started)/1000.0);state.put("error","");LocalDate earliest=LocalDate.now(ZoneId.of("Asia/Shanghai")).minusDays(6);try(DirectoryStream<Path> archives=Files.newDirectoryStream(dir,"beauty-v3-*.zip")){for(Path file:archives){String fileName=file.getFileName().toString();if(fileName.matches("beauty-v3-[0-9]{4}-[0-9]{2}-[0-9]{2}\\.zip")&&LocalDate.parse(fileName.substring(10,20)).isBefore(earliest))Files.delete(file);}}Files.write(dir.resolve("status.json"),JSON.toJSONBytes(state));return state;}catch(Exception e){Map<String,Object> existing=status();existing.remove("running");existing.put("error","最近一次备份未完成，请检查服务与磁盘，修复后重试。");existing.put("lastAttempt",Instant.now().toString());Files.write(dir.resolve("status.json"),JSON.toJSONBytes(existing));throw e;}finally{if(process!=null&&process.isAlive())process.destroyForcibly();Files.deleteIfExists(dump);Files.deleteIfExists(tmp);running=false;}}
 private void entry(ZipOutputStream zip,Path file,String name)throws IOException{zip.putNextEntry(new ZipEntry(name));Files.copy(file,zip);zip.closeEntry();}
 private void tree(ZipOutputStream zip,Path source,String prefix)throws IOException{if(!Files.exists(source))return;final Path base=source.toAbsolutePath().normalize();try(java.util.stream.Stream<Path> paths=Files.walk(base)){Iterator<Path> it=paths.iterator();while(it.hasNext()){Path path=it.next();if(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)&&!Files.isSymbolicLink(path)){ShopService.check(path.normalize().startsWith(base),"图片目录范围不正确");entry(zip,path,prefix+base.relativize(path).toString().replace('\\','/'));}}}}
}
